import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <math.h>

#define THREADS 256

__global__ void sdpa_kernel(const half* __restrict__ Q,
                             const half* __restrict__ K,
                             const half* __restrict__ V,
                             half* __restrict__ O,
                             int batch, int heads, int seqlen, int dim,
                             float scale) {
    int idx = blockIdx.x; // over batch*heads*seqlen
    int i = idx % seqlen;
    int bh = idx / seqlen;
    int h = bh % heads;
    int b = bh / heads;

    const half* Qrow = Q + (((size_t)b*heads + h)*seqlen + i)*dim;
    const half* Kbase = K + (((size_t)b*heads + h)*seqlen)*dim;
    const half* Vbase = V + (((size_t)b*heads + h)*seqlen)*dim;
    half* Orow = O + (((size_t)b*heads + h)*seqlen + i)*dim;

    extern __shared__ char smem[];
    half* qs = (half*)smem;                     // dim halfs
    float* scores = (float*)(qs + dim);          // seqlen floats
    float* red = scores + seqlen;                // THREADS floats
    int dim2 = dim >> 1;
    half2* qs2 = (half2*)qs;
    const half2* Qrow2 = (const half2*)Qrow;
    // load Q row to shared mem (vectorized half2 loads)
    for (int d2 = threadIdx.x; d2 < dim2; d2 += blockDim.x) {
        qs2[d2] = Qrow2[d2];
    }
    __syncthreads();
    // compute scores = Q . K^T * scale (vectorized half2 dot product)
    for (int j = threadIdx.x; j < seqlen; j += blockDim.x) {
        const half2* Krow2 = (const half2*)(Kbase + (size_t)j*dim);
        float sum = 0.0f;
        #pragma unroll 4
        for (int d2 = 0; d2 < dim2; d2++) {
            float2 qf = __half22float2(qs2[d2]);
            float2 kf = __half22float2(Krow2[d2]);
            sum += qf.x * kf.x + qf.y * kf.y;
        }
        scores[j] = sum * scale;
    }
    __syncthreads();
    __syncthreads();

    // compute max for numerical stability
    float local_max = -1e30f;
    for (int j = threadIdx.x; j < seqlen; j += blockDim.x) {
        local_max = fmaxf(local_max, scores[j]);
    }
    red[threadIdx.x] = local_max;
    __syncthreads();
    for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (threadIdx.x < s) red[threadIdx.x] = fmaxf(red[threadIdx.x], red[threadIdx.x + s]);
        __syncthreads();
    }
    float maxval = red[0];
    __syncthreads();

    // exponentiate and sum
    float local_sum = 0.0f;
    for (int j = threadIdx.x; j < seqlen; j += blockDim.x) {
        float e = __expf(scores[j] - maxval);
        scores[j] = e;
        local_sum += e;
    }
    red[threadIdx.x] = local_sum;
    __syncthreads();
    for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
        __syncthreads();
    }
    float sumval = red[0];
    float inv_sum = 1.0f / sumval;
    __syncthreads();

    // compute output = softmax(scores) @ V (vectorized half2 accumulation)
    half2* Orow2 = (half2*)Orow;
    for (int d2 = threadIdx.x; d2 < dim2; d2 += blockDim.x) {
        float2 acc = make_float2(0.0f, 0.0f);
        for (int j = 0; j < seqlen; j++) {
            const half2* Vrow2 = (const half2*)(Vbase + (size_t)j*dim);
            float2 vf = __half22float2(Vrow2[d2]);
            float s = scores[j];
            acc.x += s * vf.x;
            acc.y += s * vf.y;
        }
        Orow2[d2] = __floats2half2_rn(acc.x * inv_sum, acc.y * inv_sum);
    }
}

torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == torch::kFloat16, "expects fp16");

    Q = Q.contiguous();
    K = K.contiguous();
    V = V.contiguous();

    int batch = Q.size(0);
    int heads = Q.size(1);
    int seqlen = Q.size(2);
    int dim = Q.size(3);

    auto O = torch::empty_like(Q);

    float scale = 1.0f / sqrtf((float)dim);

    int grid = batch * heads * seqlen;
    int block = THREADS;

    size_t shmem = (size_t)dim * sizeof(half) + (size_t)seqlen * sizeof(float) + (size_t)block * sizeof(float);

    if (shmem > 48 * 1024) {
        cudaFuncSetAttribute(sdpa_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, shmem);
    }

    sdpa_kernel<<<grid, block, shmem>>>(
        reinterpret_cast<const half*>(Q.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(K.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(V.data_ptr<at::Half>()),
        reinterpret_cast<half*>(O.data_ptr<at::Half>()),
        batch, heads, seqlen, dim, scale
    );

    return O;
}
"""

cpp_source = r"""
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
"""

sdpa_module = load_inline(
    name="sdpa_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["sdpa_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.sdpa = sdpa_module

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return self.sdpa.sdpa_forward(Q, K, V)


batch_size = 2
num_heads = 32
sequence_length = 256
embedding_dimension = 1024


def get_inputs():
    Q = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    K = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    V = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    return [Q, K, V]


def get_init_inputs():
